{
  "themes": [
    {
      "cluster": 36,
      "name": "Subscription Billing & Cancellation Issues",
      "description": "Customers report being charged multiple times, difficulty canceling, and problems with auto‑renewal of Xbox subscriptions."
    },
    {
      "cluster": 37,
      "name": "Xbox Live Gold Activation Problems",
      "description": "Users say their Xbox Live Gold shows as active but they cannot play online or access Gold features."
    },
    {
      "cluster": 38,
      "name": "Xbox Wi‑Fi Connectivity Failures",
      "description": "Customers experience their console suddenly losing Wi‑Fi connection while other devices remain connected."
    },
    {
      "cluster": 39,
      "name": "Xbox Live Service Connection Errors",
      "description": "Even with a good network, users cannot connect to Xbox Live services and receive generic connection failure messages."
    },
    {
      "cluster": 40,
      "name": "Unresolved Error Codes After Update",
      "description": "Players receive specific error codes (e.g., 0x80040900, 0x8027025A) that persist despite standard troubleshooting steps."
    },
    {
      "cluster": 41,
      "name": "General Console Frustration & Abuse Reports",
      "description": "Feedback contains profanity and complaints about console performance, support interactions, and perceived malware."
    },
    {
      "cluster": 42,
      "name": "Backwards Compatibility Requests",
      "description": "Users ask for original Xbox titles to become playable on newer Xbox hardware."
    },
    {
      "cluster": 43,
      "name": "Game Server Lag & Crashes",
      "description": "Players report high latency, timeouts, and frequent crashes in online games such as GTA Online and PUBG."
    },
    {
      "cluster": 44,
      "name": "Poor Customer Service Experience",
      "description": "Customers describe long wait times, rude agents, and unresolved issues when contacting support."
    },
    {
      "cluster": 45,
      "name": "Account Bans & Suspensions Confusion",
      "description": "Users are unsure why their accounts are banned or suspended and seek clarification or reinstatement."
    },
    {
      "cluster": 46,
      "name": "Console Glitches & Crash Symptoms",
      "description": "Feedback mentions random freezes, gray overlay boxes, and the console failing to start properly."
    },
    {
      "cluster": 47,
      "name": "Xbox One X Enhanced Content Updates",
      "description": "Customers inquire about 4K/Enhanced game updates, pre‑downloads, and timing of content releases for Xbox One X."
    }
  ]
}
